ter;gap:12px;flex-wrap:wrap}.section-heading label{margin:0 0 16px}.register-scroll{overflow:auto;border:1px solid #dce6df;border-radius:10px}.register{border-collapse:collapse;width:max-content;min-width:100%;font-size:13px}.register th,.register td{border:1px solid #dce6df;min-width:34px;text-align:center;padding:10px 7px}.register th:first-child{min-width:140px;max-width:180px;white-space:normal;position:sticky;left:0;background:#f5f8f5;text-align:left;overflow-wrap:anywhere}.register thead{background:#f0f5f0}.present{color:#276d43}.absent{color:#a13d32;background:#fff1ef}.late{color:#8b661c;background:#fff6df}.future{color:#acb5af}.attendance-totals{display:flex;gap:10px 18px;flex-wrap:wrap;margin:18px 0;font-size:13px}.attendance-totals strong{margin-left:6px}.notice{padding:16px 0;border-bottom:1px solid #dce6df}.notice:last-child{border:0}.preserve-lines{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.routine{padding:16px 0;border-bottom:1px solid #dce6df}.routine h3{line-height:1.5}.routine ul,.menu-list,.booking-list{list-style:none;padding:0}.routine li{display:flex;align-items:start;gap:16px;padding:10px 0;font-size:14px}.routine time{font-size:12px;white-space:nowrap;min-width:88px}.routine small,.menu-list small{display:block;font-size:12px;color:#64796c;margin-top:5px}.booking-list{font-size:13px;line-height:1.7}.menu-list li{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid #dce6df;font-size:14px}.password-details{border-top:1px solid #dce6df;margin-top:24px;padding-top:16px}.password-details summary{cursor:pointer;min-height:44px}@media(max-width:600px){.parent-shell{padding:0 14px 24px}.parent-header{padding:18px 0}.parent-header h1{font-size:23px}.parent-shell .card{padding:16px}.fields,.overview-grid{grid-template-columns:1fr}.parent-tabs button{flex:1 1 100px}.routine li{gap:10px}.routine strong{font-size:13px}.parent-shell h2{font-size:19px}}
